/**
 * 缩略图加载队列
 *
 * 限制同一时间正在进行的图片请求数量。列表/卡片一次性并发太多缩略图请求时，
 * 每张缩略图都会让 Cloudflare Image Resizing 回源下载整张原图（Telegram 上的原图
 * 可达十几 MB），并发过高会把源站拖慢并触发 CF 的下载超时（ERROR 9504）。
 */

const MAX_CONCURRENT = 3;

let active = 0;
const waiters = [];

function releaseSlot() {
    active = Math.max(0, active - 1);
    const next = waiters.shift();
    if (next) next();
}

/**
 * 申请一个图片加载槽位。
 * @returns {Promise<Function>} resolve 出一个 release 函数，在图片 load/error 之后调用以释放槽位
 */
export function acquireImageSlot() {
    if (active < MAX_CONCURRENT) {
        active += 1;
        return Promise.resolve(releaseSlot);
    }
    return new Promise((resolve) => {
        waiters.push(() => {
            active += 1;
            resolve(releaseSlot);
        });
    });
}
